var e={"29268u":`RoboKit — rakit & simulasikan mobil robot`,qvztjl:`RoboKit — awal tutorial`,s42iv2:`academe.com.br (terbuka di tab baru)`,"16us7mj":`Bahasa`,ktdb8o:`Pengaturan`,"198kuu7":`Meja kerja 3D`,ia581p:`Animasi`,j4z771:`Jeda`,wlqobg:`Jeda (Spasi)`,h23ysv:`Kecepatan putar`,r953rm:`Zoom`,"19blqjd":`Perbesar`,"110wpq2":`Perkecil`,q5w460:`Tampilan`,bldqt5:`Tampilan terurai (E)`,"44cnpg":`Tampilan kejar: ikuti mobil dari belakang (C)`,"13epjbk":`Peta arena uji dari atas`,j4zjee:`Rintangan yang dipilih`,yq1vr3:`Dari titik tengah rintangan, diukur dari tengah arena, tempat mobil mulai menghadap ke atas peta`,"19kd62s":`Ubah arena`,l1a70i:`Ubah arena: pindahkan, putar, dan ubah ukuran rintangan`,"15n0apn":`Batalkan perubahan terakhir (Ctrl+Z). Ctrl+Shift+Z mengembalikannya`,j4uzpn:`Arena seperti semula, dengan mobil kembali di titik awal`,"84sbk0":`Biarkan arena seperti sebelumnya (Esc)`,"1oy9vz":`Pakai arena ini: tampilan 3D dibangun ulang dan simulasi berlanjut`,ium5z9:`Cara program mobil memutuskan`,vq0gg8:`Tutup diagram alir`,s2tc63:`Tutup (Esc)`,"13bjj4d":`Alihkan mobil ke Auto, lalu lihat caranya memutuskan`,gfubiu:`Cara program memutuskan: buka diagram alir`,"1gh0at8":`Langkah tutorial`,"61nq88":`Langkah sebelumnya`,ga5x9q:`Langkah berikutnya`,"1v1ybkn":`Kemudi`,"9anomo":`Maju (W / ↑)`,bbake2:`Belok kiri (A / ←)`,bfl95g:`Berhenti (Spasi)`,iseiwq:`Belok kanan (D / →)`,"4o292l":`Mundur (S / ↓)`,"10qzszt":`Kecepatan motor`,"2yhdcy":`Mode kemudi`,"8m10x9":`Manual (1)`,"1ogxhr7":`Menghindari rintangan (2)`,"1i3ygcv":`Matikan motor (3)`,"1dlx0na":`Buzzer (B)`,isqcd9:`Sudut servo`,"29ulgm":`Keluaran serial`,"1l0xxoj":`Tutup`,"2r1h4p":`Koneksi`,cwepyb:`Memuat…`,"10iu545":`RoboKit butuh JavaScript untuk berjalan.`,"120y7gz":`Dirancang oleh`,"1hpelzf":`Papan`,"1j2fqe6":`MEJA KERJA`,"17d8vhd":`Langkah 1 · Kumpulkan komponen`,gqo5v1:`Simulator`,"1py6ulk":`Klik untuk memeriksa`,"1ms3o1u":`Jarak`,"2w2xwg":`Kecepatan`,n44ilu:`Mode`,"1d2vfr6":`Servo`,"152va0w":`Simulasi dijeda`,"11i7yk1":`Klik rintangan untuk memilihnya.`,"1a4x3zw":`Ukuran`,"1kpdcfp":`Panjang`,gfxz9b:`Lebar`,s3robe:`Diameter`,"7puwki":`Tinggi`,kbxnhn:`Diputar`,"7nkn2r":`Posisi, dari titik awal`,v1hcj2:`Ke depan`,"1vf2pel":`Ke kanan`,"1xakelj":`Shift`,"1esrfu8":`langkah 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`ukuran dari tengah`,"1xzs12p":`pindah ·`,"14bbmnu":`putar`,g7xa5b:`Arena · 3 × 3 m`,vmlwpb:`Urungkan`,"2zps2o":`Atur ulang`,ew9em3:`Batal`,lewgh4:`Simpan`,"1vz8dhj":`Cara program memutuskan`,m76rx7:`Pilih kotak untuk melihat kodenya`,"1hnif0x":`Alur program`,"11rknnz":`Langsung`,"540b06":`Auto`,"1fr6xqr":`Kumpulkan komponen`,"1wu7r43":`Manual`,ky4lc5:`Berhenti`,"152av8f":`Aktuator`,"1df7dln":`Buzzer`,pksfl2:`kemudi ·`,"1hrh82t":`Spasi`,"9zyeew":`berhenti ·`,jw8yab:`mode ·`,j4ckle:`buzzer ·`,kzo6rh:`kejar`,mcpijf:`Monitor serial`,"1aeugy":`Bersihkan`,"1jgmzoq":`← Kembali`,c9ljxw:`langkah`,"1padbm0":`Lanjut`,g6g542:`Kembali ke langkah`,"1k7z1pa":`Esc`,dpexcn:`Spesifikasi`,"8f4gnm":`Ke langkah`,qy3p54:`PENGATURAN`,"12znfuf":`Langkah kemudi terhubung ke`,"17rhf7d":`Mobil asli (Wi-Fi ESP32)`,dsq8ip:`Alamat mobil`,"1ihj7t4":`Tampilan & suara`,oh792y:`Bunyikan buzzer lewat speaker`,"1bxmuya":`Tampilkan sorot ultrasonik`,"1gxdv01":`Kamera mengikuti mobil`,"9mmtn3":`Atur ulang simulasi`,"1k6e5zv":`Terapkan`,"1iptqu5":`URL tidak valid “{url}”`,"12bfr2h":`URL harus diawali ws:// atau wss://`,"1s22nop":`Menghubungkan ke {url}`,"1q17yrm":`Mencoba lagi dalam {s} s`,hsi0bv:`Tidak ada data dari mobil`,ye8ewg:`Terhubung`,"1puhp9v":`Menghubungkan…`,y1y3f2:`Tidak ada data`,ci4tze:`Terputus`,"1fmx9lv":`Galat koneksi`,"19wtqq3":`Terhubung · {board}`,"1b4ym3j":`Simulator bawaan`,bgnl0z:`Menyiapkan grafis`,"39rjx0":`Siap`,"1ruee97":`Meja kerja 3D tidak bisa dimulai. Ia butuh WebGL: coba browser lain, atau nyalakan akselerasi perangkat keras.`,xa5swu:`ARENA UJI`,"18xfupg":`Kemudikan dengan kontrol di kanan`,khccvm:`Kemudikan dengan W A S D atau kontrol di kanan`,vhwww6:`Langkah {n} · {title}`,"1i98668":`Merakit mobil`,y9b5jm:`Menata komponen`,qzfxj5:`Tampilkan baris {n} di meja kerja`,pj86x7:`Tampilkan ini di meja kerja`,"13bzcw5":`Disalin`,"8gdme8":`Pilih & salin`,s6g5lw:`Salin`,"1bstp0v":`Daftar bahan`,"1g4j0cl":`Yang kamu perlukan`,"15cdqf0":`Alat`,"1wrxvmg":`Lakukan ini`,"1x0ptmh":`Peta pin · {board}`,"1go9otx":`Sketch`,zvnhd5:`Sketch`,t8quxl:`Unduh`,na9qmv:`Kalau ada yang salah`,"5mau71":`Catatan`,"1xh5jos":`{kicker} · Langkah {n} dari {total}`,slbawy:`Berikutnya: {step} →`,"7rhhil":`Mulai lagi ↺`,"1mtyvb1":`Langkah {n}: {step} · {done} / {total} dicentang`,"4x1xaj":`Langkah {n}: {step}`,d2gue0:`Kotak kardus`,"1xebpbq":`Balok kayu`,hi63vm:`Kaleng`,"14yz9o9":`Pot bunga`,"1g6nbya":`Harus tetap di dalam dinding.`,v23nvk:`Tempat mobil mulai harus tetap kosong.`,"1d1sqge":`Mobil berdiri di sana.`,sjcnug:`Dua rintangan tidak bisa berada di tempat yang sama.`,"1rjq9tt":`Seret rintangan untuk memindahkannya. Pegangan persegi mengubah ukurannya, yang bulat memutarnya.`,qaws2z:`Arena dari atas. Klik rintangan untuk memilihnya, seret untuk memindahkannya. Dengan keyboard: Page Down dan Page Up memilih rintangan, tombol panah memindahkannya, R memutarnya.`,km6rtw:`Rintangan`,v6zgjh:`Arena seperti semula. Menyimpan mengembalikan mobil ke titik awalnya.`,"1bneya5":`Setiap putaran dimulai di sini`,"1gvmqkj":`Keputusan`,"2wk0tb":`Aksi`,ltbyq8:`ya`,r90oai:`tidak`,"10pfeta":`{file} · baris {lines}`,"1mv69ab":`{file} · baris {lines}`,v5glvz:`tidak ada gema`,"1y6bn7c":`kiri {left} · kanan {right}`,"17yvayv":`Jalan bebas: terus melaju`,g8loky:`{reading} di depan · berhenti di bawah {stop} cm`,"1qpxp29":`Berhenti · LED nyala · bip`,lman68:`rintangan di {reading} · di bawah {stop} cm`,"4e4gg4":`Sudah mundur sedikit: melihat sekeliling`,"1x1kke3":`pembacaan tidak berubah selama {s} s`,"1pc4lzp":`Sudah mundur: melihat lagi`,"11qad25":`kedua sisi terlalu sempit untuk berbelok`,dfsfd7:`Tersangkut: mundur sedikit`,eic5lt:`pembacaan tak berubah selama {s} s`,n7w5mt:`Tak ada ruang berbelok: mundur`,etina8:`{sides} · di bawah {tight} cm`,crgp5w:`Melihat ke kanan`,vto9jk:`membaca {reading}`,"1xubspn":`Melihat ke kiri`,"92dcjq":`kanan {right} · kiri membaca {reading}`,cfs13v:`Ada ruang berbelok?`,h7zzeh:`{sides} · butuh {tight} cm`,qlw2zr:`Belok kiri lagi`,"1fd6gkc":`Belok kanan lagi`,"1hj21ci":`terhalang tepat setelah berbelok: arah yang sama`,"1jk1kpr":`Belok kiri`,u6ps9c:`Belok kanan`,"1uvg70v":`Auto mati`,"1bbdvwo":`Tampilan langsung: hanya mobil simulasi`,"1fj8dwo":`alihkan ke Auto untuk melihat mobil memutuskan`,"14g7i3l":`mobil asli melaporkan pembacaan, bukan langkah rutinnya`,"15nlm70":`Kembali ke langkah {n} · {step}`,"1i8tm8j":`Dipasang di <b>langkah ini</b>`,rpu2qi:`Dipasang di <b>langkah {n} · {step}</b>`,"1b4o3fw":`Ke langkah {n} →`,y322vs:`Bahasa: {name}`,bk85tv:`Putar`,"1x4eyna":`{action} (Spasi)`,gpdo6z:`Gunakan alamat ws:// atau wss://, mis. ws://192.168.4.1:81/`,"1iquufv":`Sambungkan dulu ke jaringan Wi-Fi mobil. Lihat README.md untuk format pesan yang harus digunakan firmware.`,njqkz2:`Masukkan URL WebSocket, mis. ws://192.168.4.1:81/`,nrzvmi:`Mengemudikan mobil simulasi di arena uji — tanpa perangkat keras.`,cegybp:`Komponen`,wv4sck:`Persiapan`,"7z3mbb":`Semua untuk rover empat roda dengan “kepala” ultrasonik yang bisa melihat sekeliling. Tata komponennya seperti ini dan centang satu per satu. Arahkan kursor ke sebuah baris untuk menemukannya di alas, atau klik komponen untuk detailnya.`,"1x97es5":`Isi daya sel 18650 dengan charger Li-ion yang benar sebelum mulai, dan pakai sel berproteksi: sel tanpa proteksi bisa mengalirkan puluhan ampere saat korsleting.`,"13wu8qd":`Sasis akrilik — dek bawah, tengah, dan atas`,"9z9vwl":`Motor gearbox TT (3–6 V, 1:48) dengan 8 braket akrilik berbentuk T, 8 baut M3 × 30 dan mur`,"1qr4ely":`Roda, 65 mm`,cmzolq:`Modul driver motor ganda L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + kabel USB`,"15cdntm":`ESP32 DevKit V1 (30 pin) + papan ekspansi + kabel USB`,mfnvxi:`Sensor ultrasonik HC-SR04 + braket servonya dan sekrup`,"15iavp3":`Servo mikro SG90 dengan lengan dan sekrup`,"1allzrf":`Sel Li-ion 18650 (berproteksi) + dudukan 2 slot seri dengan kabel`,xooybo:`Saklar geser, LED merah 10 mm, resistor 220 Ω, buzzer aktif 5 V`,"1csc29i":`Saklar geser, LED merah 10 mm, buzzer aktif 5 V, transistor NPN (PN2222A atau S8050), resistor 220 Ω, 2 × 1 kΩ dan 2 kΩ`,"17dpcif":`Colokan DC barrel dengan terminal sekrup, 5.5 × 2.1 mm`,bozwcy:`20 kabel jumper female–female, 15 cm; kabel serabut merah dan hitam; 16 spacer kuningan M3 female–female (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 sekrup M3 × 6 mm, selotip busa, selongsong heat-shrink`,"5z6ae7":`Solder, timah`,"1xhh6dp":`kabel motor, saklar, kabel LED dan buzzer`,"11dguvz":`Obeng kecil`,"1b1pnob":`plus untuk sekrup M3, minus untuk terminal driver dan colokan`,"1ligzav":`Tang potong / pengupas kabel`,"3pb5yx":`memotong dan mengupas kabel serabut dan jumper`,"1avt53n":`Multimeter`,"1slxnnr":`memeriksa polaritas sebelum daya dinyalakan`,"100w2b7":`Charger Li-ion`,"64j96q":`untuk sel 18650`,"1heknmc":`Komputer, Arduino IDE`,"1mo2nzj":`untuk mengunggah kode di langkah 9`,t9gk37:`Motor`,"15i6udf":`Rakit`,"1fofbt3":`Motor & roda`,"15llile":`Setiap motor TT adalah motor DC kecil yang memutar gearbox plastik 1:48. Dua motor kiri dan dua motor kanan selalu berputar bersama, seperti rantai tank: mobil berbelok dengan menjalankan kedua sisi pada kecepatan berbeda.`,k5fimq:`Merah di kaki dalam setiap motor-lah yang membuatmu bisa menyambung merah ke merah di langkah 4: motor depan dan belakang di satu sisi saling berhadapan, jadi kaki dalamnya punya tugas yang sama. Kakinya tipis dan bisa patah kalau kabelnya tertarik, jadi rekatkan setiap pasang kabel ke motornya dengan selotip. Kabel berdiri di tengah agar celah panjang dek tengah bisa turun melewatinya di langkah 3.`,"7fte4n":`Dek bawah`,rbcm1a:`Motor gearbox TT`,sjfn38:`Braket motor akrilik berbentuk T`,"732lu":`Baut M3 × 30 dan mur`,skq14t:`Roda`,"1s4rmq":`Letakkan keempat motor di tempatnya di dek bawah, as menghadap keluar dan ujung motor ke tengah. Solder dua kabel sepanjang sekitar 15 cm ke masing-masing: merah di kaki yang lebih dekat ke tengah mobil, hitam di kaki yang lebih dekat ke roda. Tegakkan kedelapan kabel bersama di tengah dek.`,"1mrwedd":`Angkat deknya. Dari bawah, dorong satu braket ke atas lewat celah di sisi dalam setiap motor dan satu lagi ke takik di tepi dek di sisi luarnya. Masukkan dua baut M3 × 30 melewati braket, gearbox, dan braket, kepala baut di sisi roda, lalu kencangkan mur di masing-masing.`,"13sq8kw":`Tekan roda ke setiap as. As punya dua sisi rata yang mengunci ke hub, jadi roda tidak bisa selip.`,"199dyzl":`Dek`,qr73r6:`Susun dek`,kig8cy:`Spacer kuningan mengangkat dek tengah 25 mm di atas dek bawah, melewati gearbox motor setinggi 22 mm, dan memberi elektronik lantai yang rata. Setiap spacer berulir di kedua ujung: satu sekrup masuk dari bawah lewat dek di bawahnya, satu lagi turun lewat apa pun yang ada di atasnya.`,"1w8a39y":`Akrilik retak kalau dikencangkan berlebihan, jadi cukup pas saja. Sasis berbeda-beda: kalau sasismu tidak punya lubang di tempat yang dibutuhkan kontroler, dua spacer dan sepotong selotip busa di bawah ujung lainnya bisa menahan papan dengan kokoh.`,jcqip:`Dek tengah`,u6l9bq:`Spacer kuningan M3 × 25 mm`,"4cdagt":`Spacer kuningan M3 × 10 mm (untuk kontroler)`,xaqs1y:`Spacer kuningan M3 × 15 mm (untuk dek atas)`,"300byl":`Sekrup M3 × 6 mm`,tezznv:`Sekrup delapan spacer 25 mm ke dek bawah, empat di setiap sisi, masing-masing pada sekrup yang dimasukkan dari bawah.`,"70hnlv":`Sebelum dek tengah dipasang, selagi bagian bawahnya masih terjangkau, pasang empat spacer 10 mm di bawah lubang pemasangan kontroler (pegang papan di tempatnya untuk melihat lubang dek mana yang sejajar) dan empat spacer 15 mm di sudut separuh belakangnya, masing-masing dengan sekrup dari bawah.`,"1tynoxv":`Turunkan dek tengah ke spacer 25 mm, sambil memasukkan kabel motor ke atas lewat celah panjang di tengahnya, lalu sekrup.`,"1n5adbz":`Driver`,"1ri406w":`Pasang driver motor`,"5n5nar":`Pin mikrokontroler sebaiknya tidak memberi lebih dari sekitar 20 mA, padahal motor TT menarik beberapa ratus mA saat berjalan dan lebih dari 1 A saat macet. Modul L9110S punya dua H-bridge yang mengalirkan arus baterai lewat motor dan bisa membaliknya.`,"1uicxnj":`Sekrup terminal mana yang mendapat pasangan mana belum penting: tes kabel di langkah 9 menunjukkan apakah satu sisi berputar mundur, atau satu roda berputar melawan pasangannya. Biarkan header 6 pin (B-IA, B-IB, GND, VCC, A-IA, A-IB) kosong: daya masuk di langkah 7 dan sinyal di langkah 8. L9110S menangani 800 mA per kanal, dan di sini setiap kanal menggerakkan dua motor: cukup untuk jalan normal, tapi jangan tahan roda sampai macet. Kalau chipnya panas, modul TB6612FNG (1.2 A per kanal) adalah pengganti yang lebih tangguh.`,utkklb:`Potongan selotip busa dua sisi`,syij08:`Tempel driver ke dek tengah dengan selotip busa, di depan spacer kontroler dan di kiri tengah: header 6 pin menghadap tepi kiri mobil, terminal sekrup menghadap tengah mobil.`,"15kkcap":`Tekuk kabelnya ke depan di sepanjang dek dan arahkan ke terminal driver. Pilin dua kabel merah motor kiri bersama dan dua kabel hitamnya bersama, lalu sekrup kedua pasang itu ke MOTOR-A, terminal yang lebih dekat ke kontroler. Lakukan hal yang sama dengan kabel motor kanan di MOTOR-B.`,"18rvg69":`Kontroler`,ync8b9:`Pasang Arduino UNO`,"1u68uls":`Pasang ESP32`,ertyxs:`Arduino UNO (ATmega328P, 16 MHz, logika 5 V) menjalankan sketch-mu. Sensor Shield V5 dipasang di atasnya dan memberi setiap pin header G / V / S sendiri (ground, 5 V, dan sinyal), karena header daya UNO hanya punya satu pin 5 V untuk dibagi antara servo dan sensor.`,"1p7bu2t":`ESP32 (dual-core, hingga 240 MHz, Wi-Fi dan Bluetooth, logika 3.3 V) menjalankan sketch-mu dan membuat RoboKit bisa mengemudikan mobil asli lewat Wi-Fi. Papan ekspansinya menambahkan soket DC dengan regulator dan header G / V / S untuk setiap pin.`,ii2aq7:`Pin UNO bekerja pada 5 V, jadi sensor dan servo langsung tersambung ke shield.`,"1ghuj2z":`Pin ESP32 bekerja pada 3.3 V dan tidak tahan 5 V, jadi keluaran Echo sensor diberi pembagi tegangan di langkah 8.`,t5ws5g:`ESP32 DevKit V1 (30 pin)`,"1tu8qz5":`Papan ekspansi ESP32 (30 pin)`,"14w4gx0":`Sekrup UNO ke empat spacer 10 mm di belakang driver, dengan soket USB dan DC menghadap sisi kiri mobil.`,hw767j:`Tekan Sensor Shield V5 ke UNO dengan setiap pin masuk ke soketnya. Biarkan jumper SEL terpasang, agar pin V shield mengambil 5 V dari UNO, dan jangan sambungkan apa pun ke terminal sekrup shield.`,"1opbgrl":`Sekrup papan ekspansi ke empat spacer 10 mm di belakang driver, dengan soket DC menghadap sisi kiri mobil.`,"1xxnsy2":`Pasang DevKit di dua soket sehingga setiap nama pin di atasnya cocok dengan nama yang tercetak di samping soket. Papan yang bergeser satu pin akan memberi daya ke pin yang salah.`,ua2sfx:`Atur jumper pin V ke 5 V, karena servo, HC-SR04, dan buzzer butuh 5 V. Papan ekspansi berbeda-beda, jadi periksa tanda jumper di papanmu.`,"1jzloyj":`Sensor`,"19ot7f3":`Kepala sensor`,jii9ss:`HC-SR04 memancarkan semburan ultrasonik 40 kHz dan mengukur waktu gemanya: jarak dalam cm ≈ waktu gema dalam µs ÷ 58. Ia mengukur dari 2 cm hingga sekitar 4 m dalam sorot selebar sekitar 15°. Dipasang di servo SG90, ia bisa melihat ke kiri dan kanan sebelum mobil berbelok.`,"1s5nsw8":`Untuk menengahkan servo, colokkan ke header A5 shield (cokelat ke G) dan unggah salah satu sketch dari langkah 9: keduanya membiarkan kepala di 90°. Memutar as keluaran secara paksa bisa merusak gigi plastiknya. Dengan pemasangan seperti ini, pin sensor dari kiri, dilihat dari depan: GND, Echo, Trig, VCC.`,"3b6msg":`Untuk menengahkan servo, colokkan ke header GPIO 23 (cokelat ke G, V diatur ke 5 V) dan unggah firmware langkah 9, yang setup()-nya memanggil servoWrite(90). Memutar as keluaran secara paksa bisa merusak gigi plastiknya. Dengan pemasangan seperti ini, pin sensor dari kiri, dilihat dari depan: GND, Echo, Trig, VCC.`,"2934zx":`Servo mikro SG90, lengan tunggal dan sekrup`,"1o4q0ha":`Braket servo untuk HC-SR04, dengan sekrupnya`,"87cfw2":`Sensor ultrasonik HC-SR04`,"1bhe6w2":`Pegang servo di atas lubang persegi di depan dek tengah, as keluaran di atas dan di garis tengah mobil. Masukkan colokannya ke bawah lewat lubang, ke belakang di bawah dek dan ke atas lewat celah kecil di belakangnya, lalu tarik kabelnya sampai colokan berada di dek di samping kontroler. Lalu turunkan servo ke lubang, kabelnya turun lewat takik di ujungnya, dorong sisa kabel kembali ke bawah dek, jauh dari as motor, dan sekrup kedua telinga servo ke dek.`,"7x26fs":`Tengahkan servo, lalu tekan lengan tunggal ke asnya, menghadap ke depan, dan kunci dengan sekrup lengan.`,"3f8bcm":`Sekrup braket ke lengan, tegak menghadap ke depan.`,"178kb38":`Sekrup HC-SR04 ke depan braket lewat dua lubang sudut di salah satu sisi panjangnya, dengan sisi itu di bawah dan pin di atas: kabelnya lalu keluar ke atas, jauh dari servo.`,"1jamndy":`Daya`,tboesy:`Dua sel 18650 seri memberi 7.4 V nominal (8.4 V penuh, sekitar 6 V habis). Saklar memutus kabel + baterai. Semuanya bertemu di colokan DC dengan terminal sekrup: dua kabel baterai masuk ke sana, colokan memberi daya ke UNO lewat soket DC-nya, yang regulatornya membuat 5 V untuk logika, dan dua kabel lagi dari terminal yang sama memberi daya ke driver motor. Driver tidak bisa mengambil daya dari pin 5 V shield: pin itu berasal dari regulator kecil UNO, yang akan kelebihan beban oleh empat motor. Komponen yang perlu kabel disolder mendapatkannya di meja kerja, sebelum dipasang di mobil: selipkan dulu sepotong heat-shrink ke kabel, lalu susutkan di atas sambungan setelahnya.`,r69l9i:`Dua sel 18650 seri memberi 7.4 V nominal (8.4 V penuh, sekitar 6 V habis). Saklar memutus kabel + baterai. Semuanya bertemu di colokan DC dengan terminal sekrup: dua kabel baterai masuk ke sana, colokan memberi daya ke papan ekspansi lewat soket DC-nya, yang regulatornya membuat 5 V dan 3.3 V untuk logika, dan dua kabel lagi dari terminal yang sama memberi daya ke driver motor. Driver tidak bisa mengambil daya dari pin 5 V papan: pin itu berasal dari regulator kecilnya, yang akan kelebihan beban oleh empat motor. Komponen yang perlu kabel disolder mendapatkannya di meja kerja, sebelum dipasang di mobil: selipkan dulu sepotong heat-shrink ke kabel, lalu susutkan di atas sambungan setelahnya.`,"175zcey":`Periksa polaritas dua kali sebelum memasukkan sel: soket UNO positif di tengah, dan terminal + colokan adalah pin tengahnya (periksa dengan multimeter). Isi ulang saat paket turun ke sekitar 7 V, karena di bawah itu regulator UNO tidak bisa mempertahankan 5 V. Jika tidak ada LED yang menyala, matikan segera dan periksa kabelnya sebelum mencoba lagi. LED dan buzzer tetap di meja kerja sampai langkah 8.`,t60ux3:`Periksa polaritas dua kali sebelum memasukkan sel: kebanyakan papan ekspansi positif di tengah, tapi periksa simbol di dekat soket, dan terminal + colokan adalah pin tengahnya (periksa dengan multimeter). Isi ulang saat paket turun ke sekitar 7 V. Jika tidak ada LED yang menyala, matikan segera dan periksa kabelnya sebelum mencoba lagi. LED dan buzzer tetap di meja kerja sampai langkah 8.`,mvli44:`Dek atas + 4 sekrup M3 × 6 mm`,"1dowjmo":`Dudukan 2 × 18650 dengan kabel, 2 sel`,"83x4u2":`Saklar geser`,"1in9b4e":`Colokan DC barrel dengan terminal sekrup (tengah +)`,l8wrh1:`LED merah 10 mm + resistor 220 Ω`,"24gtky":`Buzzer aktif 5 V`,"14zuroc":`Buzzer aktif 5 V, transistor NPN + resistor 1 kΩ`,"1pgj6ai":`Selotip busa, heat-shrink, 4 kabel jumper untuk dipotong: 2 merah, 2 hitam`,"1ewjpxi":`Selotip busa, heat-shrink, 5 kabel jumper untuk dipotong: 2 merah, 2 hitam, 1 oranye`,y2bs3a:`Letakkan dek atas di atas empat spacer 15 mm dan sekrup.`,anc24f:`Di meja kerja, potong kabel merah dudukan baterai sekitar 2 cm dari dudukan. Solder ujung yang dari dudukan ke salah satu pin luar saklar, dan 10 cm dari potongan tadi ke pin tengah.`,"1mixan6":`Pegang dudukan di atas dek atas, kabelnya ke arah kiri mobil. Masukkan kabel hitam ke bawah lewat lubang di tepi kiri dek dan tarik ke depan di sepanjang dek tengah sambil menurunkan dudukan. Tempel dudukan dengan dua potong selotip busa, dan saklar dalam posisi miring di tepi kiri dek, tuasnya menghadap keluar. Lalu bentangkan kabel merah ke depan, melewati sudut depan dek. Kedua kabel harus berakhir di samping soket DC kontroler.`,"1xim7b6":`Potong satu kabel jumper merah dan satu hitam 12.5 cm dari salah satu ujung. Tekan soket potongan merah yang panjang ke pin VCC driver dan yang hitam panjang ke GND, lalu bentangkan keduanya kembali di sepanjang tepi kiri dek tengah ke soket.`,"1200i":`Potong satu kabel jumper merah dan satu hitam 11 cm dari salah satu ujung. Tekan soket potongan merah yang panjang ke pin VCC driver dan yang hitam panjang ke GND, lalu bentangkan keduanya kembali di sepanjang tepi kiri dek tengah ke soket.`,"1nymzxl":`Kupas 5 mm dari keempat ujung yang bebas. Sekrup kedua yang merah di bawah sekrup + colokan dan kedua yang hitam di bawah −, lalu tekan colokan ke soket DC UNO, diputar sehingga + di atas.`,f3jc5e:`Kupas 5 mm dari keempat ujung yang bebas. Sekrup kedua yang merah di bawah sekrup + colokan dan kedua yang hitam di bawah −, lalu tekan colokan ke soket DC papan ekspansi, diputar sehingga + di atas.`,hhvzfi:`Di meja kerja, solder resistor 220 Ω seri dengan kaki panjang (+) LED. Potong satu kabel jumper merah dan satu hitam menjadi dua. Solder satu potongan merah ke ujung bebas resistor dan satu potongan hitam ke kaki pendek LED.`,"1qz1083":`Tekuk rata kedua pin buzzer. Solder potongan merah lainnya ke + (pin yang lebih panjang, bertanda di atas) dan potongan hitam lainnya ke −.`,"110bbxt":`Tekuk rata kedua pin buzzer dan solder potongan merah lainnya ke + (pin yang lebih panjang, bertanda di atas). Solder kolektor transistor ke pin − dan resistor 1 kΩ ke basisnya, lalu setengah kabel jumper oranye ke resistor dan potongan hitam lainnya ke emitor. Susutkan satu selongsong di atas transistor dan resistor. Periksa kaki mana yang mana di datasheet transistormu.`,"1avlub7":`Pastikan tidak ada sambungan telanjang yang bisa menyentuh yang lain, dan saklar dalam posisi mati. Lalu masukkan kedua sel ke dudukan, setiap ujung + di tempat yang ditandai + pada dudukan. Nyalakan sebentar: LED daya di kontroler dan di driver harus sama-sama menyala.`,k2hc2b:`Kabel`,s234wa:`Sambungkan kabel`,"1po8toc":`Setiap sensor dan aktuator dicolokkan ke header G / V / S di shield, jadi semuanya berbagi ground UNO; ground driver berasal dari baterai, yang lewat colokan DC adalah ground yang sama. Pin dipilih berdasarkan letak tiap komponen, jadi kabel menyebar dari header tanpa bersilangan. Kerjakan dengan urutan ini, saklar mati: LED dulu, rendah di ujung kiri header, dan empat kabel sensor paling akhir, karena kabel itu melengkung di atas semuanya. Kabel jumper dipasang satu ujung demi satu ujung: tekan satu soket sampai penuh ke pinnya, tekuk kabelnya, tekan yang lain. Arahkan kursor ke sebuah baris untuk melihat kabelnya di model.`,"1ylwoyd":`Setiap sensor dan aktuator dicolokkan ke header G / V / S di papan ekspansi, jadi semuanya berbagi ground ESP32; ground driver berasal dari baterai, yang lewat colokan DC adalah ground yang sama. Pin dipilih berdasarkan letak tiap komponen, jadi kabel menyebar dari header tanpa bersilangan. Kerjakan dengan urutan ini, saklar mati: LED dulu, rendah di ujung kiri header, dan kabel sensor paling akhir, karena kabel itu melengkung di atas semuanya. Kabel jumper dipasang satu ujung demi satu ujung: tekan satu soket sampai penuh ke pinnya, tekuk kabelnya, tekan yang lain. Arahkan kursor ke sebuah baris untuk melihat kabelnya di model.`,"10tvb2g":`D5 dan D11 membawa kecepatan setiap sisi: keduanya pin PWM yang tetap bekerja saat library Servo berjalan (library itu mengambil Timer1, yang mematikan PWM di D9 dan D10). D6 dan D12 membawa arah. Servo dan buzzer memakai A5 dan A0 sebagai pin digital biasa. Semua pin G tersambung, begitu juga semua pin V: GND dan VCC sensor bisa ke yang paling dekat.`,it0an4:`Pembagi 1 kΩ / 2 kΩ mengubah pulsa Echo 5 V menjadi 3.3 V (5 V × 2 ⁄ 3). Echo memakai GPIO 35, salah satu pin khusus masukan (34–39): yang perlu ia lakukan hanya membaca. Buzzer berjalan dari pin V 5 V dan transistor yang menyalakannya, karena 3.3 V di bawah kebutuhan buzzer 5 V. Keluaran menghindari GPIO 0, 2, 5, 12, 14 dan 15, yang merupakan pin strapping atau berdenyut saat ESP32 menyala. Semua pin G tersambung, begitu juga semua pin V.`,"16ffufp":`LED: tempel di dekat sudut kiri depan kontroler · merah → S · hitam → G`,"55vkwv":`Driver A-IA / A-IB (kiri)`,"1wr2rcy":`Driver B-IA / B-IB (kanan)`,"12y58k1":`Kabel servo (cokelat G, merah V, oranye S)`,"1xjcvwz":`Buzzer: tempel di depan dek atas · merah → S · hitam → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G dari D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Buzzer: tempel di depan dek atas · merah → V · oranye (basis) → S · hitam (emitor) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G dari GPIO 34`,"1ig2p4r":`HC-SR04 Echo: potong jumpernya 4.5 cm dari salah satu ujung · 1 kΩ di antara potongan · 2 kΩ lanjut ke potongan 4.7 cm dari ujung jumper hitam · potongan pendek → S dan G`,xoaiok:`Kode`,"1if8prf":`Program`,"1g03ums":`Unggah kode`,"1bv2ey7":`Dua sketch. Tes kabel memeriksa setiap komponen bergiliran, jadi kamu bisa melihat bahwa masing-masing tersambung dan kedua sisi berputar ke arah yang benar. Penghindar rintangan adalah program mobilnya: ia melaju sampai ada sesuatu lebih dekat dari 22 cm, melihat ke kanan dan kiri dengan kepalanya, lalu berbelok ke sisi yang lebih lapang.`,"8lzj5q":`Firmware ini menjadikan ESP32 titik akses Wi-Fi. Ia menjalankan perintah yang dikirim RoboKit (kemudi, kecepatan, mode, servo, LED, dan buzzer), berhenti jika perintah tidak datang lagi, dan mengirim balik jarak dan status motor 10 kali per detik. Dalam mode Auto ia menghindari rintangan sendiri, dengan rutin yang sama dengan yang dijalankan simulator.`,saufbh:`Jika tidak ada yang memantulkan ping, HC-SR04 menahan Echo tinggi selama sekitar 38 ms (angka datasheet; beberapa modul lebih lama). Itu melewati batas waktu 30 ms, jadi pulseIn() mengembalikan 0. Penghindar menghitungnya sebagai 400 cm, “bebas”, bukan “menyentuh”. Sorotnya sempit, jadi mobil bisa tersangkut di sudut yang tak pernah dilihatnya: pembacaan yang berhenti berubah sementara roda mendorong memberi tahu bahwa ia tersangkut. Dan jika ia terhalang lagi tepat setelah berbelok, ia berbelok ke arah yang sama sekali lagi, bukan berbalik: di sudut, kalau tidak begitu, ia akan belok kiri, kanan, kiri terus-menerus.`,"11hew0t":`ledcAttach() dan ledcWrite(pin, duty) adalah API arduino-esp32 3.x; panggilan lama ledcSetup() dan ledcAttachPin() dari 2.x tidak bisa dikompilasi lagi. Sorot sensor sempit, jadi dalam Auto mobil bisa tersangkut di sudut yang tak pernah dilihatnya: pembacaan yang berhenti berubah sementara roda mendorong memberi tahu bahwa ia tersangkut. Dan jika ia terhalang lagi tepat setelah berbelok, ia berbelok ke arah yang sama sekali lagi, bukan berbalik: di sudut, kalau tidak begitu, ia akan belok kiri, kanan, kiri terus-menerus.`,"3zk06m":`Di Arduino IDE, pilih Tools → Board → Arduino UNO dan port yang benar. Kedua sketch memakai library Servo, yang sudah disertakan dengan IDE.`,j0z2nr:`Ganjal mobil sehingga keempat roda tidak menyentuh meja. Unggah tes kabel, nyalakan baterai, dan buka Serial Monitor di 115200 baud. Perhatikan setiap baris bernomor terjadi: LED dan bip, kepala ke kanan, kiri, dan tengah, lalu setiap sisi maju dan mundur.`,"1dz2oap":`Perbaiki yang tidak sesuai (lihat daftar di bawah). Lalu unggah penghindar rintangan, cabut kabel USB, letakkan mobil di lantai dan nyalakan: ia menunggu dua detik, lalu berangkat.`,"4czqhs":`Ubah TURN_MS di sketch sampai setiap belokan sekitar seperempat putaran di lantaimu.`,rgjhux:`Di Arduino IDE, tambahkan https://espressif.github.io/arduino-esp32/package_esp32_index.json di File → Preferences → Additional boards manager URLs. Lalu pasang “esp32 by Espressif Systems” versi 3.x dari Boards Manager dan pilih ESP32 Dev Module.`,"118rr9r":`Dari Library Manager, pasang “WebSockets” terbaru karya Markus Sattler dan “ArduinoJson” versi 7 karya Benoit Blanchon.`,nbb8bl:`Unggah, lalu ganjal mobil sehingga keempat roda tidak menyentuh meja dan nyalakan baterai. Sambungkan ke jaringan Wi-Fi “RoboKit” (kata sandi drive1234), buka langkah 10 dan sambungkan dari Pengaturan → Mobil asli (Wi-Fi ESP32).`,srtywe:`Coba setiap kontrol bergiliran: LED, buzzer, penggeser Servo, lalu W A S D. Jika satu sisi berputar ke arah yang salah, lihat daftar di bawah. Lalu letakkan mobil di lantai, coba Auto, dan ubah TURN_MS sampai setiap belokan sekitar seperempat putaran.`,sp50jr:`Tidak ada yang menyala saat dinyalakan`,"1gg4m0p":`Matikan. Periksa apakah sel sudah terisi dan terpasang dengan benar, kabel merah ada di bawah sekrup + colokan, dan saklar tersambung antara pin tengah dan salah satu pin luarnya.`,"9crnd5":`Satu sisi berputar mundur saat tes`,"1mf4jfi":`Tukar dua kabel sisi itu di terminal sekrupnya: MOTOR-A sisi kiri, MOTOR-B sisi kanan.`,"1gcvytv":`Satu roda berputar melawan pasangannya`,"76bppn":`Tukar dua kabel motor itu di tempat kabelnya dipilin dengan kabel motor lainnya.`,kakgt9:`Baris 3 memutar roda kanan`,"95tfvz":`Dua pasang jumper tertukar: A-IA / A-IB ke D11 / D12, B-IA / B-IB ke D5 / D6.`,"1yvpqg9":`Kepala melihat ke kiri dulu`,"3fc0ov":`Beberapa servo berputar ke arah sebaliknya: tukar 20 dan 160 di sketch.`,"1ymivbo":`Jaraknya selalu 0.0 cm`,"1wzcqly":`Tidak ada gema yang kembali. Periksa apakah Trig di D4 dan Echo di D3, dan VCC dan GND sensor ada di pin V dan pin G. Ia juga membaca 0 jika tidak ada apa pun dalam sekitar 4 m.`,lg1f33:`UNO mulai ulang saat motor menyala`,gp3cr0:`Tegangan baterai turun: isi ulang sel. Kapasitor 470–1000 µF di antara V dan G pada shield (perhatikan polaritasnya) membantu suplai 5 V melewati penurunan itu.`,"13n04wo":`Mobil berdengung tapi tidak mau berputar di tempat`,y7q52i:`Berbelok menggesek keempat ban ke samping dan butuh dorongan lebih besar daripada jalan lurus: naikkan SPIN mendekati MAX_PWM, dan isi ulang sel.`,hvphiw:`Mobil menyimpang ke satu sisi`,ittf4s:`Tidak ada dua motor yang benar-benar sama. Pelankan sisi yang lebih cepat: untuk mobil yang menyimpang ke kanan, drive(CRUISE - 10, CRUISE).`,"19do8xl":`Unggahan berhenti di “Connecting…”`,hn5crr:`Tahan tombol BOOT DevKit sampai unggahan mulai, dan periksa apakah kabel USB membawa data, bukan hanya daya.`,"144ggw6":`RoboKit tidak mau tersambung`,"1wm6oj5":`Satu sisi berputar mundur`,"1buhj6h":`Kiri dan kanan tertukar`,"1s6olzj":`Dua pasang jumper tertukar: A-IA / A-IB ke GPIO 26 / 27, B-IA / B-IB ke GPIO 33 / 25.`,svln7p:`Dalam Auto, kepala melihat ke kiri dulu`,"1ki0m9i":`Beberapa servo berputar ke arah sebaliknya: tukar 20 dan 160 di autoStep().`,"6xg3a":`Jaraknya selalu 400 cm`,"7himiv":`Tidak ada gema yang kembali. Periksa apakah Trig di GPIO 32, Echo sampai ke GPIO 35 lewat pembagi, dan VCC sensor ada di pin 5 V. Ia juga membaca 400 jika tidak ada apa pun dalam sekitar 4 m.`,ksb87p:`Buzzer tetap diam`,"9czfii":`Periksa kaki transistor sesuai datasheet-nya (urutannya berbeda antar jenis), dan pastikan + buzzer ada di pin 5 V.`,igpqu0:`ESP32 mulai ulang saat motor menyala`,owaty5:`Tegangan baterai turun: isi ulang sel. Kapasitor 470–1000 µF di antara pin 5 V dan G (perhatikan polaritasnya) membantu suplai melewati penurunan itu.`,"1u5gnnb":`Berbelok menggesek keempat ban ke samping dan butuh dorongan lebih besar daripada jalan lurus: naikkan kecepatan, dan isi ulang sel.`,uak3xr:`1 · Tes kabel`,"1jz093b":`2 · Penghindar rintangan`,"129dlzg":`Firmware`,ussxe7:`Simulasi`,"17ssthc":`Kemudikan`,bmzqy4:`Mobil simulasi punya komponen yang sama dengan mobilmu. Kemudikan di arena uji, lalu alihkan ke Auto: ia menjalankan rutin yang sama dengan sketch penghindar rintangan. Ia berhenti dan berbunyi bip di depan rintangan, melihat ke kanan dan kiri, berbelok ke sisi yang lebih lapang, dan mundur saat tersangkut.`,"189d210":`Mobil simulasi menjawab perintah yang sama dengan yang dikirim RoboKit ke ESP32-mu, dan Auto menjalankan rutin yang sama dengan firmware. Setelah mobilmu jadi, beralihlah ke sana di Pengaturan → Mobil asli (Wi-Fi ESP32).`,olmdkx:`Roda, 65 mm`,psly3z:`Penggerak`,vffqvh:`Ban karet pada pelek plastik. Hub-nya punya lubang dengan dua sisi rata yang ditekan ke as keluaran motor TT, jadi roda tidak bisa selip. Saat mobil berputar di tempat, ban menggesek ke samping, jadi cengkeraman penting.`,jq4v4c:`Hub`,mq93xq:`lubang dua sisi rata untuk as motor TT`,"1cgpuek":`Jarak per putaran`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Motor gearbox TT`,m5llum:`Motor DC sikat kecil yang memutar gearbox plastik 1:48. Balik arusnya dan roda berputar ke arah lain; turunkan tegangan rata-rata dengan PWM dan ia melambat.`,"525amd":`Tegangan`,"226us9":`Rasio gigi`,jpnnsq:`≈ 200 rpm pada 6 V, tanpa beban`,"1dw4k8q":`Arus`,"1p9wnb6":`≈ 150 mA tanpa beban · hingga ≈ 1.5 A saat macet pada 6 V`,cdauuh:`Torsi macet`,"1gzxf67":`≈ 0.8 kg·cm pada 6 V`,ign4wl:`Badan`,mad9cv:`As`,"14e36jb":`Ø 5.5 mm dengan dua sisi rata berjarak 3.7 mm, keluar di kedua sisi`,feutd2:`Pemasangan`,"183nrmx":`dua lubang Ø 3 mm berjarak 17.5 mm, 20 mm di belakang as`,"108seeu":`Braket motor`,"1mquwkf":`Sasis`,"10qeeg1":`Potongan akrilik berbentuk T. Batangnya naik lewat dek bawah di samping gearbox dan kepalanya tetap di bawah, jadi tidak bisa tertarik lolos. Satu dipasang di tiap sisi motor, dan dua baut panjang melewati kedua braket dan dua lubang pemasangan gearbox.`,"1kk17cw":`Bahan`,"1me4wyg":`akrilik`,st0e1p:`Per motor`,"8uzq1j":`2 braket · 2 baut M3 × 30 + mur`,"1am47c9":`Dipasang`,v6cwyh:`dari bawah dek: yang dalam di sebuah celah, yang luar di takik di tepi`,"723pu9":`Membawa keempat motor dan delapan spacer untuk dek tengah. Sebuah celah dan sebuah takik di tepinya di samping setiap motor menerima dua braket motor itu.`,"1n7meho":`Ukuran (model ini)`,r4lxco:`Lantai elektronik. Celah panjang di tengah memungkinkan kabel motor naik dari bawah, dan lubang persegi di depan menahan servo; takik di ujungnya untuk kabel servo.`,"11vqw8c":`25 mm di atas dek bawah`,"1957t19":`Dek atas`,"2ljc6y":`Dek setengah panjang di belakang yang menahan paket baterai, saklar, dan buzzer di atas elektronik.`,"1ytak7b":`1.5 cm di atas dek tengah`,"1ey525v":`Spacer kuningan, M3`,"7je4w9":`Spacer segi enam berulir di kedua ujung. Mereka menjaga jarak antar dek dan mengangkat papan sirkuit dari akrilik agar tidak ada bagian bawahnya yang menyentuh.`,"1t2znv5":`Ulir`,i9dhsi:`M3, female–female`,"1cazjzs":`dek bawah → tengah (melewati motor 22 mm)`,rni6ay:`dek tengah → atas`,"1dz3bjd":`papan kontroler`,"1erre2c":`Sekrup`,"7fsd49":`M3 × 6 mm di setiap ujung, total 32`,pmsrct:`Kabel motor`,h0ivdz:`Kabel merah dan hitam dari setiap motor: merah di kaki yang lebih dekat ke tengah mobil, hitam di yang lebih dekat ke roda. Dua motor di setiap sisi disambung paralel ke satu kanal driver, merah dengan merah dan hitam dengan hitam, jadi keduanya selalu berputar bersama.`,"148isqp":`masing-masing sekitar 15 cm`,"88dh10":`Pasangan kiri`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Pasangan kanan`,"1il2rct":`MOTOR-B`,"4iibl6":`Satu sisi berputar mundur?`,"1p9lbgb":`tukar kedua pasangnya di terminal`,"2380z5":`Satu roda melawan pasangannya?`,h5sbfv:`tukar dua kabel motor itu`,"19qn9l6":`Driver motor L9110S`,"82whm4":`Elektronik`,"12ibf8u":`Dua chip H-bridge L9110S, satu per kanal. Setiap kanal punya dua masukan: IA tinggi dan IB rendah memutar motor ke satu arah, IA rendah dan IB tinggi ke arah lain, dan keduanya sama menghentikannya. PWM di salah satu masukan mengatur kecepatan.`,"25ul91":`Suplai (VCC)`,m2phlf:`800 mA per kanal (puncak 1.5–2 A)`,"17s6ks8":`Masukan`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · logika 3.3 V atau 5 V`,"4swwow":`Header`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (pin siku)`,"1xbblqt":`sekitar 29 × 23 mm, lubang pemasangan Ø 3 mm (ukuran berbeda tiap penjual)`,"189a81e":`Papan mikrokontroler ATmega328P. Ia menjalankan sketch-mu, membaca sensor, dan memutuskan apa yang dilakukan motor.`,"1ebaepz":`ATmega328P @ 16 MHz`,"16qkmtv":`Level logika`,eslzkd:`Pin PWM`,oopaku:`Memori`,"8hfwsd":`32 KB flash · 2 KB RAM`,"1jzh7y5":`Daya masuk`,"1vbs2jm":`7–12 V di soket DC (disarankan)`,"1hxwxrt":`Arus pin`,xms582:`20 mA disarankan · 40 mA batas mutlak`,"1n28mf4":`Dipasang di atas UNO dan membawa setiap pin ke header G / V / S 3 pin (ground, 5 V, sinyal), jadi servo atau sensor bisa langsung dicolokkan dengan ground dan suplainya sendiri.`,e8ir2h:`Header`,d0uaj4:`D0–D13 dan A0–A5, masing-masing G · V · S`,"1iy90zn":`Pin V`,ohp32m:`5 V dari UNO selama jumper SEL terpasang`,"1y4aysj":`Tanpa jumper`,gi4ocs:`V berasal dari terminal sekrup shield`,"1thlwjq":`Perhatian`,"1fzsig9":`jangan pernah memberi daya ke terminal sekrup saat SEL terpasang`,"1kft85q":`Tambahan`,"1e4238k":`header I²C dan serial`,"1jeelmn":`ESP32 DevKit + papan ekspansi`,"8jd2d6":`Mikrokontroler dual-core dengan Wi-Fi dan Bluetooth, dipasang di papan ekspansi yang menambahkan soket DC dengan regulator dan header G / V / S untuk setiap pin.`,"1inmx8d":`Modul`,qx458t:`ESP32-WROOM-32 · hingga 240 MHz`,"7ra2ga":`3.3 V, tidak tahan 5 V`,"1chl2hi":`pin keluaran mana saja (LEDC)`,"7fk3dd":`Nirkabel`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V di soket DC (periksa papanmu)`,yzyhje:`3.3 V atau 5 V, diatur dengan jumper`,"7wntef":`Servo mikro SG90`,mni0ct:`Motor kecil, gearbox, dan sensor posisi dalam satu wadah. Ia mengharapkan pulsa setiap 20 ms (50 Hz); lebar pulsa mengatur sudut: 1.5 ms adalah tengah, dan sekitar 0.5–2.4 ms mencakup 0° hingga 180°.`,wvoosj:`Torsi`,"1e13gca":`≈ 0.1 s per 60°`,"1yo9wk7":`Ukuran · berat`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Kabel`,"1qalf36":`cokelat GND · merah V+ · oranye sinyal`,"1bshntj":`Braket servo HC-SR04`,"1yr5sge":`Disekrup ke lengan servo dan menahan HC-SR04 lewat dua lubang sudutnya, jadi sensor berputar bersama servo dan sorotnya tetap datar.`,"1t4m9bk":`Pengikat`,mnle4w:`sekrup lengan servo`,"1yzxd81":`Menahan`,"1fp9bdu":`HC-SR04 lewat dua lubang sudutnya, di atas spacer`,"1yozvc2":`Jenis lain`,"16fhes5":`banyak braket justru menjepit sensor pada dua transduser-nya`,c8gdr7:`Pulsa 10 µs di Trig membuat satu transduser mengirim delapan siklus 40 kHz; yang lain mendengarkan. Echo lalu tetap tinggi selama waktu yang dibutuhkan suara untuk pergi dan kembali, jadi cm = µs ÷ 58 (343 m/s, dibagi dua).`,"198uyr6":`Jangkauan`,"3xsn4q":`Sorot`,"1gw4v0v":`di bawah 15°`,"1oy2zwu":`Suplai`,"1m7niep":`Laju ping`,"7gsn1j":`satu setiap 60 ms atau lebih lambat`,npm5w4:`Pin (depan, kiri → kanan)`,pyp646:`VCC · Trig · Echo · GND dengan pin di bawah; dipasang dengan pin di atas, seperti di sini: GND · Echo · Trig · VCC`,cr1wqh:`Paket Li-ion 2 × 18650`,"1fdnj4z":`Dua sel seri: 8.4 V saat penuh, 7.4 V nominal, sekitar 6 V saat habis. Pakai sel berproteksi, jangan pernah dikorsletingkan, dan isi dayanya dengan charger Li-ion yang benar.`,w63ube:`7.4 V nominal (6–8.4 V)`,serueh:`Kapasitas`,"1lup9sh":`2000–3500 mAh (sel asli)`,"7l22en":`Dudukan`,"1ka7i4l":`2 slot, seri`,"1h1ba5m":`sel berproteksi beberapa mm lebih panjang; pastikan muat`,h4px5m:`Saklar daya`,bs7ocz:`Memutus kabel + baterai, jadi seluruh mobil mati. Ia disambung antara pin tengah dan salah satu pin luarnya: kabel merah dudukan di satu pin, kabel ke colokan di pin lainnya. Ia berbaring miring di atas selotip busa di tepi kiri dek atas, tuas menghadap keluar, di tempat yang terjangkau jari.`,"1m2zofh":`Jenis`,"69jc9h":`saklar geser SPDT dipakai sebagai on/off`,w3vkqt:`Pin`,"1owufyi":`tiga berderet: luar · bersama · luar`,fph5dc:`Rating`,"1bpycfc":`pilih yang ber-rating ≥ 2 A DC`,k3s7zg:`Buzzer aktif, 5 V`,"177ed2m":`Sinyal`,jfbt4g:`Ia punya osilator sendiri di dalamnya: buat pin HIGH dan ia berbunyi bip dengan nada tetap, tanpa perlu kode tone(). Ia menarik hingga sekitar 25–30 mA: masih di dalam batas mutlak 40 mA pin, tapi di atas 20 mA yang biasanya disarankan, jadi menyalakannya lewat transistor NPN adalah kebiasaan yang lebih aman.`,xscire:`Ia punya osilator sendiri di dalamnya: beri daya dan ia berbunyi bip dengan nada tetap. Buzzer aktif 5 V bekerja mulai sekitar 3.5–4 V ke atas, jadi pin 3.3 V tidak bisa menjalankannya dengan andal. Di sini ia berjalan dari pin V 5 V dan transistor NPN, yang dikendalikan GPIO 21, menyalakannya.`,"1p7q9i9":`Nada`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Tegangan kerja`,"2tl42a":`5 V (bekerja dari ≈ 3.5–4 V ke atas, tergantung pembuat)`,"1udh5u4":`≈ 25–30 mA pada 5 V`,"1xat3vm":`berjarak 7.6 mm`,"1yzktex":`Polaritas`,"1tmcwg9":`pin yang lebih panjang / “+” di atas = +`,i8lb7k:`LED merah 10 mm`,"513nhj":`Arus mengalir dari kaki panjang (anoda, +) ke kaki pendek (katoda, −, di sisi rata pinggirannya). Ia selalu butuh resistor seri. Di sini ia berbaring miring di dekat sudut kiri depan kontroler, menyala ke arah kiri mobil.`,"17jikfo":`Tegangan maju`,"1g61wql":`maks. 20 mA`,u532rf:`Resistor 220 Ω`,"17qhgqf":`Membatasi arus LED: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Gelang warnanya merah, merah, cokelat: 2, 2 dan × 10 = 220 Ω.`,"1kwszon":`Membatasi arus LED: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Gelang warnanya merah, merah, cokelat: 2, 2 dan × 10 = 220 Ω.`,zzpczz:`Gelang`,"7ytjo4":`merah · merah · cokelat · emas`,"1llx3uw":`Toleransi`,"3389ey":`Pembagi Echo · 1 kΩ + 2 kΩ`,i8pnlw:`Keluaran Echo HC-SR04 naik sampai 5 V, tapi pin ESP32 hanya menerima paling tinggi 3.3 V. Dua resistor seri dari Echo ke ground membentuk pembagi: GPIO membaca tegangan di resistor 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Gelang 1 kΩ`,"89urq0":`cokelat · hitam · merah · emas`,"1ypqwgn":`Gelang 2 kΩ`,"1ywrkmt":`merah · hitam · merah · emas`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ dari GPIO 35 ke G`,aarp77:`Dibutuhkan untuk`,"15e8vss":`hanya ESP32`,"1aqlq1n":`Transistor buzzer · NPN + 1 kΩ`,vudz42:`Transistor NPN bekerja sebagai saklar: arus kecil ke basisnya membuat arus yang lebih besar mengalir dari kolektor ke emitor. GPIO 21 mengendalikan basis lewat 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, lebih dari cukup untuk menyalakan ≈ 30 mA buzzer dari pin 5 V.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 atau NPN serupa`,"1tlwyig":`Kolektor`,"18vf2cp":`buzzer −`,"19phq7s":`Basis`,hrttng:`1 kΩ → S dari GPIO 21`,"10ztoj1":`Emitor`,"1m0unsb":`G dari GPIO 21`,"16l0jzg":`Kaki`,v4q23:`periksa susunan pin di datasheet-nya`,gy95h:`Kabel serabut`,"170hkbj":`Kabel serabut merah dan hitam untuk kabel motor. Potong sesuai panjang sambil bekerja.`,"19d4ccc":`Merah`,ch832v:`kaki yang lebih dekat ke tengah mobil, di setiap motor`,bxogn8:`Hitam`,"1xdely8":`kaki yang lebih dekat ke roda`,"114bxvb":`Kabel jumper female–female`,tq3ghm:`Kabel Dupont dengan soket di kedua ujung yang ditekan ke pin header berjarak 2.54 mm. Masukan driver dan sensor memakai satu jumper utuh per pin. Dipotong dua, satu jumper menjadi kabel dengan soket di satu ujung: untuk komponen yang disolder (LED, buzzer) dan untuk suplai driver, yang ujung lainnya masuk ke bawah sekrup colokan.`,xe6ekx:`Jarak pin`,terfe0:`15 cm (yang 20 cm juga bisa: menyisakan lengkungan lebih besar)`,q9r4h7:`Dipakai utuh`,"16oowgw":`8: empat masukan driver, empat pin sensor`,"1rf1gzr":`7: empat masukan driver, tiga pin sensor`,onu7hf:`Dipotong`,"38aacf":`4: satu merah dan satu hitam dibelah dua untuk kabel LED dan buzzer, satu merah dan satu hitam dipotong 12.5 cm dari satu ujung untuk suplai driver`,"3iidc0":`6: satu merah dan satu hitam dibelah dua untuk kabel LED dan buzzer, satu oranye dibelah dua untuk basis transistor, satu merah dan satu hitam dipotong 11 cm dari satu ujung untuk suplai driver, dan kabel Echo sensor untuk pembaginya`,"14fe75h":`Kabel jumper · sensor ultrasonik`,f96u6l:`Empat jumper dari header sensor, yang ada di atas, melengkung kembali ke shield. Pin V dan pin G mana pun bisa dipakai untuk VCC dan GND: yang terdekat dipakai, jadi keempat kabel menyebar berdampingan.`,tuihok:`Empat kabel dari header sensor, yang ada di atas, melengkung kembali ke papan ekspansi. Echo adalah sinyal 5 V, jadi ia melewati pembagi 1 kΩ / 2 kΩ (disolder di dalam jumpernya, di bawah heat-shrink) sebelum mencapai GPIO 3.3 V.`,ftyyiy:`V dari D4`,"1xuokt7":`Trig`,o3rtpx:`S dari D4`,gi87tw:`Echo`,m5ulv4:`S dari D3`,y9urxb:`G dari D2`,"1n4125d":`V dari GPIO 32 (diatur ke 5 V)`,p5iwlb:`S dari GPIO 32`,"1aj3mnm":`1 kΩ → S dari GPIO 35 · 2 kΩ dari situ ke G-nya`,p0bbcd:`G dari GPIO 34`,"1kn37ri":`Kabel jumper · driver motor`,oiporr:`Empat masukan driver. Setiap pasang mengendalikan satu sisi mobil: IA membawa kecepatannya, di pin PWM, dan IB arahnya.`,z48w8g:`Empat masukan driver, masing-masing di pin yang mendukung PWM. Setiap pasang mengendalikan satu sisi mobil.`,"11ubulz":`A-IA / A-IB (kiri)`,jf4uze:`B-IA / B-IB (kanan)`,"15oeqsr":`Kabel servo`,wowqjs:`Kabel tiga kawat bawaan servo. Ia turun lewat lubang dan naik lewat celah di sampingnya, kembali di sepanjang dek di samping kontroler dan ke header belakang; sisanya dilipat di bawah dek. Colokan 3 jalurnya pas ke header G / V / S sekaligus: cokelat ke G.`,v89fad:`Kabel tiga kawat bawaan servo. Ia turun lewat lubang dan naik lewat celah di sampingnya, kembali di sepanjang dek di samping kontroler dan ke header belakang; sisanya dilipat di bawah dek. Colokan 3 jalurnya pas ke header G / V / S sekaligus: cokelat ke G. Baris V harus diatur ke 5 V.`,r6nyn:`Cokelat`,"1u2gqme":`Oranye (sinyal)`,"1qoi1mz":`S dari A5`,ovg5ed:`S dari GPIO 23`,"1uovlnp":`Kabel LED`,"1mffxae":`Setengah jumper merah dan setengah jumper hitam, disolder ke LED dengan soket di ujung lainnya. Anoda lewat resistor 220 Ω ke pin sinyal; katoda ke ground.`,elp8sy:`Anoda (lewat 220 Ω)`,k62hvj:`S dari D13`,ilk009:`Katoda`,k48vv7:`G dari D13`,tbj8zu:`S dari GPIO 13`,imqrdy:`G dari GPIO 13`,"1indwkw":`Kabel buzzer`,"1c2cbqo":`Setengah jumper merah dan setengah jumper hitam disolder ke pin buzzer. Buat kabel + HIGH untuk berbunyi bip.`,epsmo4:`Buzzer berada di antara pin V 5 V dan transistor. Buat GPIO 21 HIGH dan transistor menyambungkan − buzzer ke ground, jadi ia berbunyi bip.`,"1rigupw":`S dari A0`,"1yvwce0":`G dari A0`,"1tndblu":`V dari GPIO 21 (5 V)`,i73cl5:`kolektor transistor`,a4pty4:`Basis (lewat 1 kΩ)`,obgy0f:`S dari GPIO 21`,g663eg:`Kabel daya`,wp3j1m:`Semuanya bertemu di colokan DC dengan dua terminal sekrup, yang ditekan ke soket DC UNO. Baterai + mencapai terminal + lewat saklar; baterai − langsung ke terminal −. Kabel merah kedua dan kabel hitam kedua di bawah dua sekrup yang sama membawa tegangan baterai ke pin VCC dan GND driver. Driver tidak bisa diberi daya dari pin 5 V shield sebagai gantinya: pin itu disuplai regulator UNO, yang paling banyak mampu beberapa ratus mA.`,"1gazt2h":`Semuanya bertemu di colokan DC dengan dua terminal sekrup, yang ditekan ke soket DC papan ekspansi. Baterai + mencapai terminal + lewat saklar; baterai − langsung ke terminal −. Kabel merah kedua dan kabel hitam kedua di bawah dua sekrup yang sama membawa tegangan baterai ke pin VCC dan GND driver. Driver tidak bisa diberi daya dari pin 5 V papan sebagai gantinya: pin itu disuplai regulatornya, yang paling banyak mampu beberapa ratus mA.`,"1wuyp3l":`baterai + (lewat saklar)`,"161fdmk":`baterai − = GND`,"6j9255":`Colokan`,"1qkac6a":`colokan barrel 5.5 × 2.1 mm, tengah +, dengan terminal sekrup`,"1s864ea":`Di bawah setiap sekrup`,wj14kx:`dua kabel: satu dari baterai, satu ke driver`,oz5l6a:`Penghindar rintangan`,zj0mwn:`Ukur jarak`,"9jogsy":`Setiap kali loop() berputar, sensor mengirim ping. Sketch juga mencatat kapan terakhir kali pembacaan berubah lebih dari {changeCm} cm: pembacaan yang tetap diam sementara roda mendorong adalah tanda bahwa mobil tersangkut.`,"1va2b8a":`Jalan bebas?`,yssn5p:`Apakah jalan bebas?`,zou1hc:`Bebas berarti tidak ada apa pun lebih dekat dari {stopCm} cm (STOP_CM), dan pembacaan masih berubah. Lalu mobil terus melaju, dan bertanya lagi {pingMs} ms kemudian.`,"164owbk":`Terus melaju`,"2guryp":`LED mati, kedua sisi maju dengan CRUISE, dan tunggu {pingMs} ms: selama itulah sensor perlu jeda di antara dua ping. Lalu kembali ke awal.`,l1vybm:`Berhenti
LED nyala · bip`,ywa890:`Berhenti, LED nyala, bip pendek`,"17krb65":`Terhalang atau tersangkut: motor berhenti, LED menyala dan buzzer berbunyi selama {beepMs} ms.`,"1njcbjw":`Tersangkut?`,"6b9vj0":`Tersangkut pada sesuatu yang luput dari sorot?`,"12aymoo":`Sorot sensor hanya sekitar 15° lebarnya, jadi mobil bisa tersangkut di sudut yang tak pernah dilihatnya. Jika pembacaan tidak berubah lebih dari {changeCm} cm selama {stuckMsS}, padahal jalan tampak bebas, mobil tersangkut. (Tanpa gema sama sekali, 400, tidak pernah dihitung: ruang terbuka bukan “tersangkut”.)`,"7k6lib":`Mundur sedikit`,ooiwv8:`Ia mundur dari yang menahannya selama {backOffMsS}, dan baru setelah itu melihat sekeliling.`,"1d4sv1w":`Lihat kanan, lalu kiri`,"18crqcc":`Kepala berputar ke {lookRight}° (kanan) dan ke {lookLeft}° (kiri). Setiap kali, servo diberi {settleMsS} untuk sampai ke sana sebelum sensor dibaca; kedua pembacaan dicetak.`,"1r9o4nf":`Ada ruang untuk berbelok?`,"122yr22":`Jika tidak ada sisi yang punya {tightCm} cm (TIGHT_CM), tidak ada ruang untuk berbelok di sini.`,"1i7u6tc":`Mundur, lihat lagi`,"1ik4v71":`Mundur dan lihat lagi`,a0a741:`Terkepung: ia mundur selama {backMsS} lalu melihat ke kanan dan kiri lagi dari sana, sesering yang diperlukan.`,"1yfjvg4":`Baru saja berbelok?`,"2jbjim":`Terhalang lagi tepat setelah berbelok?`,"3dv25u":`Kepala kembali ke tengah. Lalu: jika belokan terakhir selesai kurang dari {againMsS} yang lalu, mobil hampir tidak bergerak sejak berbelok.`,"1steplx":`Arah yang sama lagi`,kn4k3y:`Belok ke arah yang sama lagi`,"1k7wpmb":`Berbalik arah hanya akan membawanya ke tempat semula: di sudut ia akan belok kiri, kanan, kiri terus-menerus. Jadi ia terus berbelok ke arah belokan terakhirnya, apa pun kata kedua pembacaan.`,"1lf2d81":`Sisi yang lebih lapang`,"1u19y2l":`Belok ke sisi yang lebih lapang`,"1n1zre5":`Kiri jika pembacaan di kiri setidaknya sebesar yang di kanan, selain itu kanan.`,"5j8yhm":`Belok`,"4h9f4g":`Kedua sisi berputar berlawanan selama TURN_MS ({turnMs} ms, sekitar seperempat putaran: sesuaikan dengan lantaimu). Lalu mobil berhenti, mengingat ke arah mana dan kapan ia berbelok, dan loop() mulai lagi dari atas.`,mz8bk9:`Mode Auto`,rg9t88:`Sepuluh kali per detik loop() mengirim ping ke sensor dan menyimpan pembacaan di distance (yang sekaligus dikirim ke RoboKit). Dalam mode Auto, autoStep() lalu memutuskan apa yang dilakukan dengannya.`,"15ai7e9":`Terhalang berarti ada sesuatu lebih dekat dari {stopCm} cm (STOP_CM). Pembacaan bisa berumur hingga {sampleMsS}, jadi tepat setelah berbelok ia menunggu {freshMs} ms untuk pembacaan yang diambil menghadap arah baru. Selain itu mobil terus melaju.`,"1wwbbaz":`Selama melaju, dir bernilai "forward": akhir loop() mengubahnya menjadi dua kecepatan motor, pada kecepatan yang diatur RoboKit.`,q8ujdx:`Sorot sensor hanya sekitar 15° lebarnya, jadi mobil bisa tersangkut di sudut yang tak pernah dilihatnya. Jika pembacaan tidak berubah lebih dari {changeCm} cm selama {stuckMsS} saat melaju, mobil tersangkut: ia mundur sedikit sebelum melihat sekeliling. (Tanpa gema sama sekali, 400, tidak pernah dihitung: ruang terbuka bukan “tersangkut”.)`,"1e83w8t":`Kepala berputar ke {lookRight}° (kanan), lalu ke {lookLeft}° (kiri). Setiap pembacaan diambil setelah servo sempat sampai ke sana, dan kepala kembali ke tengah.`,"1pjappa":`Jika belokan terakhir selesai kurang dari {againMsS} yang lalu, mobil hampir tidak bergerak sejak berbelok. (Menyalakan Auto memulai dari awal: turnedAt saat itu 0.)`,pjp20w:`Berbalik arah hanya akan membawanya ke tempat semula: di sudut ia akan belok kiri, kanan, kiri terus-menerus. Jadi goLeft dibiarkan apa adanya, dan mobil berbelok ke arah belokan terakhirnya, apa pun kata kedua pembacaan.`,ihilws:`Kedua sisi berputar berlawanan selama TURN_MS ({turnMs} ms, sekitar seperempat putaran: sesuaikan dengan lantaimu). Lalu LED mati, waktunya dicatat, dan mobil melaju lagi.`,"1k1y69x":`4× motor TT`,"15bpusl":`8× braket motor`,dgwrs0:`Baut M3, mur, sekrup`,"1mkf3n0":`4× roda, 65 mm`,"19aemsl":`Driver L9110S`,"123jzux":`bantalan busa`,a4iz5j:`Papan ekspansi ESP32`,"1al7iyf":`braket sensor`,a89ttz:`Servo SG90`,"1alynuo":`lengan servo`,"1pbblc6":`Dudukan 2 × 18650`,muur5i:`2× sel 18650`,"1t10ooq":`saklar daya`,"7h9qib":`buzzer aktif`,"1uw5qdo":`colokan DC`,"1l9u4j2":`16× spacer M3`,hiufn9:`kabel serabut`,"1w4hkux":`20× kabel jumper (F–F, 15 cm)`,"1onzquf":`dek bawah`,"1h4bzq9":`dek tengah`,myp2cd:`dek atas`,pu413r:`Browser memblokir ws:// dari halaman https:// — jalankan RoboKit di komputermu (npm run dev) untuk menjangkau mobil`,tqkecz:`Halaman ini disajikan lewat https, jadi browser tidak mengizinkannya membuka ws:// ke mobil. Untuk mengemudikan mobil asli, jalankan RoboKit di komputermu (npm install, lalu npm run dev) dan buka http://localhost:5173.`,vqmrol:`Komputermu harus berada di jaringan “RoboKit”, dan RoboKit harus dibuka lewat http://, bukan https://: browser memblokir ws:// dari halaman aman, jadi salinan yang di-hosting di web tidak bisa menjangkau mobil. Jalankan di komputermu (npm install selagi masih ada internet, lalu npm run dev) dan buka http://localhost:5173.`};export{e as default};